/* 학습 해설
 * IRQ 연결 해제 순서: 새 요청 차단·실행 동기화·역매핑 제거
 * 조회 표만 먼저 지운다고 진행 중인 IRQ 처리와 컨트롤러 설정이 모두 끝나는 것은 아니므로 해제에는 순서가 필요합니다.
 * irq_domain_disassociate는 irq_data가 없거나 소속 domain이 다르면 경고 후 반환합니다. 기존 hwirq를 보관하고 root mutex를 잡은 뒤 IRQ_NOREQUEST를 세우고 chip/handler 설정 helper에 NULL 인자를 전달합니다. setter 내부가 기본 chip이나 처리 함수를 선택할 수 있으므로 인자 NULL과 실제 저장 필드가 NULL이라는 주장은 구분해야 합니다. synchronize_irq로 실행과 동기화하고 unmap 콜백이 있으면 호출합니다. smp_mb 뒤 domain=NULL, hwirq=0, mapcount 감소를 수행하고 보관한 hwirq의 역매핑을 지운 뒤 잠금을 풉니다. descriptor 번호 자체를 이 함수가 free하는 것은 아닙니다.
 * mapcount=3인 유효 연결 하나를 제거하면 2가 되는 과정을 그리고, 소속이 잘못된 입력에서는 이 감소가 일어나지 않음을 확인하세요. 역매핑 삭제에 초기 hwirq를 보관한 이유를 설명하세요.
 */
static void irq_domain_disassociate(struct irq_domain *domain, unsigned int irq)
{
	struct irq_data *irq_data = irq_get_irq_data(irq);
	irq_hw_number_t hwirq;

	if (WARN(!irq_data || irq_data->domain != domain,
		 "virq%i doesn't exist; cannot disassociate\n", irq))
		return;

	hwirq = irq_data->hwirq;

	mutex_lock(&domain->root->mutex);

	irq_set_status_flags(irq, IRQ_NOREQUEST);

	/* remove chip and handler */
	irq_set_chip_and_handler(irq, NULL, NULL);

	/* Make sure it's completed */
	synchronize_irq(irq);

	/* Tell the PIC about it */
	if (domain->ops->unmap)
		domain->ops->unmap(domain, irq);
	smp_mb();

