/* 학습 해설
 * 직접 IRQ 매핑: Linux 번호를 하드웨어 번호로 함께 쓰기
 * 컨트롤러가 발생시킬 하드웨어 번호를 선택할 수 있으면 Linux가 배정한 번호를 그대로 사용해 변환 단계를 단순화할 수 있습니다.
 * CONFIG_IRQ_DOMAIN_NOMAP에서 irq_create_direct_mapping은 NULL domain을 기본 domain으로 대체하고 1부터 descriptor 번호를 할당합니다. virq가 0이면 실패입니다. virq>=hwirq_max면 범위 오류를 출력하고 descriptor 해제를 요청해 0입니다. 범위 안이면 associate(domain,virq,virq)로 두 번호를 같게 연결하고 실패 시 descriptor를 해제합니다. 이 wrapper는 기본 domain도 NULL인지 별도로 검사하지 않으며 NO_MAP 플래그를 직접 세우지도 않습니다.
 * 새 virq=12, hwirq_max=16이면 hwirq도 12로 연결합니다. virq=16이면 상한 밖입니다. 유효한 domain을 준비한 호출 계약 아래 사용하는 API라는 점을 적으세요.
 */
unsigned int irq_create_direct_mapping(struct irq_domain *domain)
{
	struct device_node *of_node;
	unsigned int virq;

	if (domain == NULL)
		domain = irq_default_domain;

	of_node = irq_domain_get_of_node(domain);
	virq = irq_alloc_desc_from(1, of_node_to_nid(of_node));
	if (!virq) {
		pr_debug("create_direct virq allocation failed\n");
		return 0;
	}
	if (virq >= domain->hwirq_max) {
		pr_err("ERROR: no free irqs available below %lu maximum\n",
			domain->hwirq_max);
		irq_free_desc(virq);
		return 0;
	}
	pr_debug("create_direct obtained virq %d\n", virq);

	if (irq_domain_associate(domain, virq, virq)) {
		irq_free_desc(virq);
		return 0;
	}

