/* 학습 해설
 * 새 IRQ 매핑 할당: 번호 확보 후 연결 실패 되돌리기
 * 새 Linux IRQ 번호를 얻는 데 성공했어도 컨트롤러 연결이 거절되면 번호를 반납해야 반복 실패로 자원이 새지 않습니다.
 * irq_create_mapping_affinity_locked는 domain의 OF 노드에서 NUMA 힌트를 얻고 irq_domain_alloc_descs(-1,1,hwirq,node,affinity)로 하나를 요청합니다. signed int virq가 0 이하이면 실패 0입니다. 양수여도 associate_locked가 실패하면 irq_free_desc 후 0입니다. 성공하면 virq를 반환합니다. 이 함수는 이름의 locked처럼 바깥 root mutex 보유 경로에서 호출되며 공개 associate를 다시 불러 같은 mutex를 중첩 획득하지 않습니다.
 * 번호 할당 실패, 번호 성공·map 실패, 모두 성공의 자원 표를 그리세요. hwirq 힌트를 넘긴다는 사실이 반환된 virq와 hwirq의 숫자 동일성을 보장하지는 않습니다.
 */
static unsigned int irq_create_mapping_affinity_locked(struct irq_domain *domain,
						       irq_hw_number_t hwirq,
						       const struct irq_affinity_desc *affinity)
{
	struct device_node *of_node = irq_domain_get_of_node(domain);
	int virq;

	pr_debug("irq_create_mapping(0x%p, 0x%lx)\n", domain, hwirq);

	/* Allocate a virtual interrupt number */
	virq = irq_domain_alloc_descs(-1, 1, hwirq, of_node_to_nid(of_node),
				      affinity);
	if (virq <= 0) {
		pr_debug("-> virq allocation failed\n");
		return 0;
	}

	if (irq_domain_associate_locked(domain, virq, hwirq)) {
		irq_free_desc(virq);
		return 0;
	}

	pr_debug("irq %lu on domain %s mapped to virtual irq %u\n",
		hwirq, of_node_full_name(of_node), virq);

	return virq;

