/* 학습 해설
 * 기존 IRQ 매핑 재사용: 검사와 생성 사이 경쟁을 막기
 * 같은 하드웨어 번호를 두 CPU가 동시에 요청하면 둘 다 없다고 보고 서로 다른 Linux 번호를 생성하지 않도록 검사와 생성을 연결해야 합니다.
 * irq_create_mapping_affinity는 NULL domain을 기본값으로 바꾸고 그래도 NULL이면 경고 후 0입니다. root mutex를 잡은 상태에서 irq_find_mapping을 호출합니다. 기존 virq가 있으면 새 번호를 할당하지 않고 그것을 반환합니다. 없으면 잠금 안에서 mapping_affinity_locked로 생성하고 공통 out에서 잠금을 풉니다. 기존 매핑 재사용 시 새 affinity 인자를 다시 적용하는 코드는 없습니다. 반환 번호의 트리거 설정도 이 함수가 자동으로 전부 결정하지 않습니다.
 * hwirq 5의 첫 요청이 virq 40을 만든 뒤 두 번째 요청이 같은 40을 얻는 흐름을 그리세요. 두 번째 호출의 affinity가 달라도 기존 경로에서는 생성 helper를 부르지 않는다는 점을 확인하세요.
 */
unsigned int irq_create_mapping_affinity(struct irq_domain *domain,
					 irq_hw_number_t hwirq,
					 const struct irq_affinity_desc *affinity)
{
	int virq;

	/* Look for default domain if necessary */
	if (domain == NULL)
		domain = irq_default_domain;
	if (domain == NULL) {
		WARN(1, "%s(, %lx) called with NULL domain\n", __func__, hwirq);
		return 0;
	}

	mutex_lock(&domain->root->mutex);

	/* Check if mapping already exists */
	virq = irq_find_mapping(domain, hwirq);
	if (virq) {
		pr_debug("existing mapping on virq %d\n", virq);
		goto out;
	}

	virq = irq_create_mapping_affinity_locked(domain, hwirq, affinity);
out:
	mutex_unlock(&domain->root->mutex);

