/* 학습 해설
 * Firmware IRQ 변환: translate·xlate·기본 셀의 우선순위
 * 펌웨어가 IRQ를 표현하는 숫자 배열은 컨트롤러마다 의미가 다를 수 있어 어느 해석 함수를 사용할지 먼저 선택해야 합니다.
 * irq_domain_translate는 계층형 domain 지원 빌드에서 ops->translate가 있으면 그 결과를 바로 반환합니다. 아니면 xlate가 있을 때 fwnode를 OF 노드로 바꾸고 param 배열과 개수를 넘깁니다. 둘 다 선택되지 않으면 param[0]을 hwirq로 쓰고 0입니다. 기본 경로는 type을 설정하지 않고 param_count도 검사하지 않습니다. 호출자인 irq_create_fwspec_mapping은 type을 NONE으로 초기화하지만 이 helper 자체가 어떤 입력도 안전하게 검사한다는 뜻은 아닙니다.
 * translate가 실패를 반환했을 때 xlate로 재시도하는지 화살표를 그려 보세요. 즉시 return이므로 재시도가 없습니다. 기본 경로에는 최소 한 개의 유효한 param이 필요하다는 계약을 적으세요.
 */
static int irq_domain_translate(struct irq_domain *d,
				struct irq_fwspec *fwspec,
				irq_hw_number_t *hwirq, unsigned int *type)
{
#ifdef CONFIG_IRQ_DOMAIN_HIERARCHY
	if (d->ops->translate)
		return d->ops->translate(d, fwspec, hwirq, type);
#endif
	if (d->ops->xlate)
		return d->ops->xlate(d, to_of_node(fwspec->fwnode),
				     fwspec->param, fwspec->param_count,
				     hwirq, type);

	/* If domain has no translation, then we assume interrupt line */
	*hwirq = fwspec->param[0];
	return 0;
}

