/* 학습 해설
 * IRQ 매핑 처분: 연결 해제와 descriptor 반납을 이어 붙이기
 * 매핑을 없앨 때 번호 대응만 지우고 descriptor를 남기거나 반대로 descriptor만 해제하면 자원이 남거나 오래된 연결이 생길 수 있습니다.
 * irq_dispose_mapping은 virq가 0이면 데이터를 조회하지 않고 반환합니다. 데이터가 없어도 반환하며 domain이 NULL이면 경고 후 반환합니다. 계층형 domain은 irq_domain_free_one_irq에 맡깁니다. 비계층 domain은 irq_domain_disassociate로 연결을 해제한 다음 irq_free_desc로 번호 객체를 반납합니다. 등록된 장치 handler를 free_irq하는 API와는 역할이 다르므로 매핑이 더는 사용되지 않는 호출 수명 계약을 지켜야 합니다.
 * 앞 단원에서 disassociate만으로 descriptor를 free하지 않았던 부분을 이 함수가 어떻게 완성하는지 그리세요. 0 입력이 유효 IRQ를 찾아 없애는 요청으로 사용되지 않는 것도 확인하세요.
 */
void irq_dispose_mapping(unsigned int virq)
{
	struct irq_data *irq_data;
	struct irq_domain *domain;

	irq_data = virq ? irq_get_irq_data(virq) : NULL;
	if (!irq_data)
		return;

	domain = irq_data->domain;
	if (WARN_ON(domain == NULL))
		return;

	if (irq_domain_is_hierarchy(domain)) {
		irq_domain_free_one_irq(domain, virq);
	} else {
		irq_domain_disassociate(domain, virq);
		irq_free_desc(virq);
	}
}
EXPORT_SYMBOL_GPL(irq_dispose_mapping);

