/* 학습 해설
 * 직접 매핑 조회: 같은 숫자여도 소속과 hwirq를 확인한다
 * NOMAP 경로에서는 하드웨어 번호를 Linux 번호로 사용할 수 있지만 그 번호의 객체가 해당 domain에 속하는지 확인하지 않으면 다른 IRQ를 반환할 수 있습니다.
 * __irq_resolve_mapping은 NULL domain을 기본값으로 대체하고 여전히 없으면 NULL입니다. NOMAP이면 hwirq<hwirq_max일 때 irq_domain_get_irq_data(domain,hwirq)로 데이터를 찾습니다. 데이터가 있고 저장된 data->hwirq도 입력과 같으면 descriptor를 얻습니다. 출력 irq 포인터가 있고 descriptor도 찾았을 때만 *irq=hwirq를 기록합니다. 실패 시 출력 칸을 자동 0으로 만드는 코드는 없습니다. 이 NOMAP 분기는 아래 일반 경로의 RCU 구간에 들어가지 않습니다.
 * 출력 변수에 처음 99가 들어 있고 조회에 실패하는 예를 그리세요. 반환 descriptor는 NULL이어도 출력 변수 99가 그대로일 수 있으므로 성공 여부를 먼저 검사해야 합니다.
 */
struct irq_desc *__irq_resolve_mapping(struct irq_domain *domain,
				       irq_hw_number_t hwirq,
				       unsigned int *irq)
{
	struct irq_desc *desc = NULL;
	struct irq_data *data;

	/* Look for default domain if necessary */
	if (domain == NULL)
		domain = irq_default_domain;
	if (domain == NULL)
		return desc;

	if (irq_domain_is_nomap(domain)) {
		if (hwirq < domain->hwirq_max) {
			data = irq_domain_get_irq_data(domain, hwirq);
			if (data && data->hwirq == hwirq)
				desc = irq_data_to_desc(data);
			if (irq && desc)
				*irq = hwirq;
		}

		return desc;
	}

	rcu_read_lock();

