/* 학습 해설
 * 한 셀 IRQ 규격: 최소 길이 검사와 NONE 트리거
 * 펌웨어 IRQ 규격이 숫자 하나로 하드웨어 번호만 표현한다면 존재하지 않는 두 번째 셀을 읽어 트리거를 추측하면 안 됩니다.
 * irq_domain_translate_onecell은 param_count<1이면 경고 후 -EINVAL입니다. 통과하면 첫 param을 out_hwirq에 기록하고 out_type=IRQ_TYPE_NONE, 성공 0입니다. OF 전용 irq_domain_xlate_onecell도 intsize<1 검사 뒤 intspec[0]과 NONE을 기록합니다. 두 함수 모두 정확히 길이 1만 허용하는 비교가 아니라 최소 길이 검사이므로 추가 셀이 있어도 이 함수에서는 뒤 셀을 읽지 않습니다. OF onecell 본문은 d와 ctrlr 인자를 사용하지 않으며 intspec과 출력 포인터의 NULL 검사도 하지 않습니다. 길이 검사는 유효 포인터와 올바른 컨트롤러 선택까지 보장하는 검사가 아닙니다.
 * 셀 [9]와 셀 [9,4]를 비교하면 이 onecell 함수의 결과는 모두 hwirq=9,type=NONE입니다. 실제 컨트롤러 binding이 추가 셀을 허용하는지는 별도 규격과 호출자의 검증 문제입니다.
 */
int irq_domain_translate_onecell(struct irq_domain *d,
				 struct irq_fwspec *fwspec,
				 unsigned long *out_hwirq,
				 unsigned int *out_type)
{
	if (WARN_ON(fwspec->param_count < 1))
		return -EINVAL;
	*out_hwirq = fwspec->param[0];
	*out_type = IRQ_TYPE_NONE;
	return 0;
}
EXPORT_SYMBOL_GPL(irq_domain_translate_onecell);

