/* 학습 해설
 * IRQ 번호 할당 힌트: 나머지 연산과 낮은 번호 재탐색
 * 하드웨어 번호와 가까운 범위에서 Linux 번호를 찾고 싶어도 그 위치가 막혀 있을 수 있어 검색 힌트와 실제 배정 결과를 구분해야 합니다.
 * virq>=0이면 그 번호를 지정해 __irq_alloc_descs를 한 번 호출합니다. 음수이면 hwirq%nr_irqs를 hint로 삼고 0이면 1로 올려 요청합니다. 결과가 0 이하이고 hint>1일 때만 1부터 다시 시도합니다. cnt·NUMA node·THIS_MODULE·affinity를 하위 할당기에 넘기고 최종 결과를 그대로 반환합니다. hint는 원하는 검색 시작점이며 hwirq와 virq가 같다는 보장이 아닙니다. 나머지 연산은 nr_irqs가 유효한 양수인 환경 계약에 의존합니다.
 * hwirq=37,nr_irqs=16이면 hint=5입니다. 첫 시도가 실패하면 1부터 재탐색합니다. hwirq=32면 나머지 0을 1로 바꾸므로 같은 1 시작 재시도를 다시 하지 않습니다.
 */
int irq_domain_alloc_descs(int virq, unsigned int cnt, irq_hw_number_t hwirq,
			   int node, const struct irq_affinity_desc *affinity)
{
	unsigned int hint;

	if (virq >= 0) {
		virq = __irq_alloc_descs(virq, virq, cnt, node, THIS_MODULE,
					 affinity);
	} else {
		hint = hwirq % nr_irqs;
		if (hint == 0)
			hint++;
		virq = __irq_alloc_descs(-1, hint, cnt, node, THIS_MODULE,
					 affinity);
		if (virq <= 0 && hint > 1) {
			virq = __irq_alloc_descs(-1, 1, cnt, node, THIS_MODULE,
						 affinity);
		}
	}

	return virq;
}

