/* 학습 해설
 * 계층형 IRQ domain 생성: 부모 연결과 크기 0의 의미
 * 한 인터럽트가 여러 컨트롤러 단계를 통과하면 각 단계의 번호 대응을 부모 관계로 표현해야 합니다.
 * 이 함수는 fwnode·size·hwirq_max·ops·host_data·flags·parent를 irq_domain_info에 넣습니다. size가 0이면 hwirq_max를 ~0U로 바꾸고 공통 instantiate를 호출합니다. IS_ERR 결과는 NULL로 바꾸므로 호출자는 이 wrapper에서 구체적인 음수 오류를 받지 못합니다. size가 양수이면 선형 역매핑 크기로 전달하고 0이면 트리 경로를 사용합니다. 여기서 부모 관계를 지정하는 일과 특정 IRQ의 각 단계 데이터를 할당하는 일은 별개입니다.
 * size=16과 size=0을 비교해 info.size와 info.hwirq_max 두 칸을 채우세요. 이 wrapper가 직접 인터럽트 handler를 등록하는 코드인지도 확인하세요.
 */
struct irq_domain *irq_domain_create_hierarchy(struct irq_domain *parent,
					    unsigned int flags,
					    unsigned int size,
					    struct fwnode_handle *fwnode,
					    const struct irq_domain_ops *ops,
					    void *host_data)
{
	struct irq_domain_info info = {
		.fwnode		= fwnode,
		.size		= size,
		.hwirq_max	= size,
		.ops		= ops,
		.host_data	= host_data,
		.domain_flags	= flags,
		.parent		= parent,
	};
	struct irq_domain *d;

	if (!info.size)
		info.hwirq_max = ~0U;

	d = irq_domain_instantiate(&info);
	return IS_ERR(d) ? NULL : d;
}
EXPORT_SYMBOL_GPL(irq_domain_create_hierarchy);

