/* 학습 해설
 * 부모 irq_data 추가: 공유 상태와 단계별 상태 나누기
 * 각 컨트롤러 단계에는 별도 하드웨어 번호와 chip 정보가 필요하지만 하나의 Linux IRQ라는 공통 정보는 함께 사용해야 합니다.
 * child의 NUMA node를 사용해 kzalloc_node로 irq_data 하나를 0 초기화해 할당합니다. 성공하면 child->parent_data에 연결하고 새 객체의 irq와 common을 child에서 복사하며 domain은 인자로 받은 값으로 지정합니다. common은 포인터 값 복사이므로 공통 객체를 새로 복제하지 않습니다. 할당 실패하면 NULL을 반환하고 성공 분기의 child 포인터 대입도 수행하지 않습니다. hwirq와 chip 등은 이 함수에서 실제 컨트롤러 값으로 설정되지 않습니다.
 * child.irq=100, child.common=P일 때 새 parent의 irq와 common을 적으세요. P가 가리키는 객체 하나를 두 data가 공유하는 그림을 그리세요.
 */
static struct irq_data *irq_domain_insert_irq_data(struct irq_domain *domain,
						   struct irq_data *child)
{
	struct irq_data *irq_data;

	irq_data = kzalloc_node(sizeof(*irq_data), GFP_KERNEL,
				irq_data_get_node(child));
	if (irq_data) {
		child->parent_data = irq_data;
		irq_data->irq = child->irq;
		irq_data->common = child->common;
		irq_data->domain = domain;
	}

	return irq_data;
}

