/* 학습 해설
 * 부모 사슬 메모리 해제: 다음 주소를 먼저 읽는 이유
 * 연결 리스트 노드를 먼저 free한 뒤 그 노드에서 다음 주소를 읽으면 이미 해제된 메모리에 접근하게 됩니다.
 * 현재 irq_data가 있으면 tmp에 보관하고 irq_data를 현재 노드의 parent_data로 먼저 이동시킨 뒤 kfree(tmp)합니다. NULL에 도달할 때까지 반복하며 입력이 NULL이면 아무것도 하지 않습니다. 이 함수는 전달받은 첫 노드부터 모두 해제하므로 descriptor 안에 포함된 첫 irq_data를 무조건 넘기는 용도가 아닙니다. chip 자원 해제 콜백이나 역매핑 삭제도 이 루프에는 없습니다.
 * A→B→NULL에서 첫 반복의 tmp=A, 다음 irq_data=B, free(A) 순서를 종이에 적으세요. free(A) 다음 A->parent_data를 읽는 순서와 비교하세요.
 */
static void __irq_domain_free_hierarchy(struct irq_data *irq_data)
{
	struct irq_data *tmp;

	while (irq_data) {
		tmp = irq_data;
		irq_data = irq_data->parent_data;
		kfree(tmp);
	}
}

static void irq_domain_free_irq_data(unsigned int virq, unsigned int nr_irqs)
{
	struct irq_data *irq_data, *tmp;
	int i;

	for (i = 0; i < nr_irqs; i++) {
		irq_data = irq_get_irq_data(virq + i);
		tmp = irq_data->parent_data;
		irq_data->parent_data = NULL;
		irq_data->domain = NULL;

		__irq_domain_free_hierarchy(tmp);
	}
}

