/* 학습 해설
 * IRQ 부모 데이터 일괄 할당: 부분 실패와 현재 번호까지 되돌리기
 * 여러 IRQ에 부모 데이터를 붙이다 중간 할당이 실패하면 앞에서 성공한 IRQ와 현재 IRQ의 일부 부모까지 함께 정리해야 합니다.
 * 각 virq+i의 descriptor에 내장된 첫 irq_data에 domain을 지정하고 domain->parent부터 부모 domain을 따라 동적 irq_data를 연결합니다. 부모 삽입이 실패하면 irq_domain_free_irq_data(virq,i+1)로 지금 번호까지 정리하고 -ENOMEM입니다. 모두 성공하면 0입니다. 첫 data를 조회한 뒤 NULL 검사가 없으므로 descriptor 범위가 이미 준비됐다는 계약이 필요합니다. 이 함수는 역매핑 등록이나 컨트롤러 alloc 콜백 실행을 하지 않습니다.
 * 100·101·102를 요청했고 i=1의 두 번째 부모에서 실패했다고 가정하세요. 100의 모든 부모와 101의 이미 만든 부모를 정리하지만 아직 시작하지 않은 102는 포함하지 않는 이유를 쓰세요.
 */
static int irq_domain_alloc_irq_data(struct irq_domain *domain,
				     unsigned int virq, unsigned int nr_irqs)
{
	struct irq_data *irq_data;
	struct irq_domain *parent;
	int i;

	/* The outermost irq_data is embedded in struct irq_desc */
	for (i = 0; i < nr_irqs; i++) {
		irq_data = irq_get_irq_data(virq + i);
		irq_data->domain = domain;

		for (parent = domain->parent; parent; parent = parent->parent) {
			irq_data = irq_domain_insert_irq_data(parent, irq_data);
			if (!irq_data) {
				irq_domain_free_irq_data(virq, i + 1);
				return -ENOMEM;
			}
		}
	}

	return 0;
}

