/* 학습 해설
 * IRQ 단계 설정: chip 기본값과 역매핑 갱신의 구별
 * 부모 계층 중 올바른 단계에 번호와 chip을 기록해야 다른 컨트롤러의 정보를 덮어쓰지 않습니다.
 * domain과 virq에 맞는 data를 검색하고 없으면 -ENOENT입니다. 있으면 hwirq와 chip_data를 대입하고 chip 인자가 NULL이면 &no_irq_chip을 저장합니다. 성공은 0입니다. 입력 chip은 const 포인터지만 저장할 때 명시적 형 변환을 사용하며 chip 객체를 복사하는 것이 아닙니다. 이 함수에는 기존 역매핑 키 삭제나 새 키 등록이 없으므로 이미 공개된 매핑을 임의로 바꾸는 일반 재배치 API로 보면 안 됩니다.
 * 자식 A와 부모 B 중 B를 선택해 hwirq=40을 넣는 그림을 그리세요. chip=NULL일 때 저장되는 값은 NULL이 아닌 기본 객체 주소라는 점을 표시하세요.
 */
int irq_domain_set_hwirq_and_chip(struct irq_domain *domain, unsigned int virq,
				  irq_hw_number_t hwirq,
				  const struct irq_chip *chip,
				  void *chip_data)
{
	struct irq_data *irq_data = irq_domain_get_irq_data(domain, virq);

	if (!irq_data)
		return -ENOENT;

	irq_data->hwirq = hwirq;
	irq_data->chip = (struct irq_chip *)(chip ? chip : &no_irq_chip);
	irq_data->chip_data = chip_data;

	return 0;
}
EXPORT_SYMBOL_GPL(irq_domain_set_hwirq_and_chip);

