/* 학습 해설
 * IRQ 최상위 해제: 전체 범위의 handler 정리를 먼저 하기
 * 상위 정리 경로에서는 부모 자원에 위임하기 전에 각 IRQ의 흐름 처리 연결과 부가 데이터를 정리해야 합니다.
 * 각 virq+i에 대해 irq_set_handler_data로 NULL을 설정하고 irq_set_handler로 NULL을 전달합니다. 모든 번호의 이 두 호출을 끝낸 뒤 irq_domain_free_irqs_common을 범위 전체에 한 번 호출합니다. 번호 하나의 handler와 부모 정리를 완전히 끝낸 다음 다음 번호로 가는 구조가 아닙니다. 본문에는 descriptor 반납이나 synchronize_irq를 직접 호출하는 코드가 없으므로 전체 수명 보호를 이 함수 하나로 단정하면 안 됩니다.
 * 번호 100·101에서 실행 순서를 data100→handler100→data101→handler101→common(100,2)로 적으세요. 이 함수와 common의 책임 차이를 비교하세요.
 */
void irq_domain_free_irqs_top(struct irq_domain *domain, unsigned int virq,
			      unsigned int nr_irqs)
{
	int i;

	for (i = 0; i < nr_irqs; i++) {
		irq_set_handler_data(virq + i, NULL);
		irq_set_handler(virq + i, NULL);
	}
	irq_domain_free_irqs_common(domain, virq, nr_irqs);
}

static void irq_domain_free_irqs_hierarchy(struct irq_domain *domain,
					   unsigned int irq_base,
					   unsigned int nr_irqs)
{
	unsigned int i;

	if (!domain->ops->free)
		return;

	for (i = 0; i < nr_irqs; i++) {
		if (irq_domain_get_irq_data(domain, irq_base + i))
			domain->ops->free(domain, irq_base + i, 1);
	}
}

