 * domain->ops->free가 없으면 즉시 반환합니다. 있으면 irq_base부터 nr_irqs개를 순회하고 각 번호에 해당 domain의 irq_data가 있는 경우에만 free(domain,해당번호,1)을 호출합니다. 전체 범위를 한 번에 넘기는 형태가 아닙니다. 이미 trim된 사슬 등에서 없는 단계를 건너뛸 수 있습니다. free 콜백은 void이므로 이 helper가 정리 실패 코드를 모아 반환하는 구조도 아닙니다.
 * 100·101·102 중 101에 domain data가 없다면 콜백 인자는 (100,1),(102,1) 두 번임을 적으세요. 총 nr_irqs=3을 그대로 한 번 전달하는 경우와 비교하세요.
 */
static void irq_domain_free_irqs_hierarchy(struct irq_domain *domain,
					   unsigned int irq_base,
					   unsigned int nr_irqs)
{
	unsigned int i;

	if (!domain->ops->free)
		return;

	for (i = 0; i < nr_irqs; i++) {
		if (irq_domain_get_irq_data(domain, irq_base + i))
			domain->ops->free(domain, irq_base + i, 1);
	}
}

