/* 학습 해설
 * IRQ 범위 해제: 역매핑·컨트롤러·부모 데이터·번호 순서
 * 번호부터 먼저 반납하면 다른 사용자가 같은 번호를 받았는데 옛 연결이나 실행이 남는 문제가 생길 수 있어 정리 순서를 지켜야 합니다.
 * 시작 virq의 data·domain·free 콜백이 없으면 경고 후 반환합니다. root mutex 안에서 범위의 모든 IRQ에 remove_irq를 호출하여 요청 제한·실행 동기화·역매핑 제거를 수행하고, 계층 free helper를 호출합니다. mutex를 푼 다음 부모 irq_data를 해제하고 마지막에 irq_free_descs로 번호 범위를 반납합니다. 첫 번호에서 얻은 domain을 전체 범위 정리에 사용하며 각 번호가 적절히 할당된 범위라는 계약이 필요합니다. 이 함수는 free_irq로 등록된 action을 해제하는 요청을 대신하지 않습니다.
 * 100·101의 역매핑을 모두 지운 뒤 컨트롤러 콜백, unlock, 부모 데이터, descriptor 순서로 표시하세요. 하나의 번호를 끝까지 정리한 후 다음 번호로 가는 구조와 비교하세요.
 */
void irq_domain_free_irqs(unsigned int virq, unsigned int nr_irqs)
{
	struct irq_data *data = irq_get_irq_data(virq);
	struct irq_domain *domain;
	int i;

	if (WARN(!data || !data->domain || !data->domain->ops->free,
		 "NULL pointer, cannot free irq\n"))
		return;

	domain = data->domain;

	mutex_lock(&domain->root->mutex);
	for (i = 0; i < nr_irqs; i++)
		irq_domain_remove_irq(virq + i);
	irq_domain_free_irqs_hierarchy(domain, virq, nr_irqs);
	mutex_unlock(&domain->root->mutex);

	irq_domain_free_irq_data(virq, nr_irqs);
	irq_free_descs(virq, nr_irqs);
}

