/* 학습 해설
 * IRQ 하나 처분: MSI device와 일반 계층 경로 구분
 * 하나의 IRQ라도 MSI device domain은 전용 자원 관리 경로가 있어 일반 범위 해제만으로 같은 절차라고 가정하면 안 됩니다.
 * irq_domain_is_msi_device(domain)이 참이면 msi_device_domain_free_wired(domain,virq)를 호출합니다. 아니면 irq_domain_free_irqs(virq,1)에 위임합니다. 이 helper는 void이고 실패 코드를 생성하거나 반환하지 않습니다. 일반 분기에는 domain 인자를 넘기지 않으며 하위 free_irqs가 virq의 data에서 실제 domain을 얻습니다. 주어진 domain과 virq의 관계가 올바른 호출 문맥이라는 전제를 확인해야 합니다.
 * MSI device 여부에 따라 두 화살표를 그리고 일반 경로에 전달되는 개수가 1임을 적으세요. 함수 이름의 one이 모든 종류에 같은 free 절차를 강제하는 것은 아님을 설명하세요.
 */
static void irq_domain_free_one_irq(struct irq_domain *domain, unsigned int virq)
{
	if (irq_domain_is_msi_device(domain))
		msi_device_domain_free_wired(domain, virq);
	else
		irq_domain_free_irqs(virq, 1);
}

/**
 * irq_domain_alloc_irqs_parent - Allocate interrupts from parent domain
 * @domain:	Domain below which interrupts must be allocated
 * @irq_base:	Base IRQ number
 * @nr_irqs:	Number of IRQs to allocate
 * @arg:	Allocation data (arch/domain specific)
 */
int irq_domain_alloc_irqs_parent(struct irq_domain *domain,
				 unsigned int irq_base, unsigned int nr_irqs,
				 void *arg)
{
	if (!domain->parent)
		return -ENOSYS;

	return irq_domain_alloc_irqs_hierarchy(domain->parent, irq_base,
					       nr_irqs, arg);
}
EXPORT_SYMBOL_GPL(irq_domain_alloc_irqs_parent);

