/* 학습 해설
 * IRQ 활성 상태 wrapper: 중복 실행 방지와 reserve 전달
 * 이미 활성화된 IRQ를 다시 설정하거나 비활성 IRQ를 중복 해제하지 않으려면 상태 비트와 실제 콜백 실행을 연결해야 합니다.
 * activate wrapper는 irq_data가 activated 상태가 아닐 때만 내부 재귀를 호출합니다. 결과가 0이면 activated 비트를 설정하며 이미 활성 상태이면 재귀 없이 0으로 끝납니다. reserve는 벡터를 실제 배정하는 대신 예약하도록 하위 콜백에 전달하는 인자입니다. reserve=true의 성공도 이 wrapper는 activated로 표시합니다. deactivate wrapper는 비트가 켜졌을 때만 재귀 비활성화를 수행하고 그 뒤 비트를 지웁니다. 둘 다 처음 상태 helper를 호출하므로 NULL 입력을 허용하는 내부 재귀와 동일한 계약으로 보면 안 됩니다.
 * 비활성→activate 성공→activate 재호출→deactivate→deactivate 재호출 순서에서 실제 재귀 호출 횟수를 적으세요. 첫 reserve=true 성공 뒤 reserve=false 재호출도 이 wrapper에서는 활성 비트 때문에 건너뛸 수 있음을 확인하세요.
 */
int irq_domain_activate_irq(struct irq_data *irq_data, bool reserve)
{
	int ret = 0;

	if (!irqd_is_activated(irq_data))
		ret = __irq_domain_activate_irq(irq_data, reserve);
	if (!ret)
		irqd_set_activated(irq_data);
	return ret;
}

/**
 * irq_domain_deactivate_irq - Call domain_ops->deactivate recursively to
 *			       deactivate interrupt
 * @irq_data: outermost irq_data associated with interrupt
 *
 * It calls domain_ops->deactivate to program interrupt controllers to disable
 * interrupt delivery.
 */
void irq_domain_deactivate_irq(struct irq_data *irq_data)
{
	if (irqd_is_activated(irq_data)) {
		__irq_domain_deactivate_irq(irq_data);
		irqd_clr_activated(irq_data);
	}
}

