/* 학습 해설
 * IRQ 계층 판별: alloc 콜백과 빌드 설정 분기
 * 같은 커널 소스도 설정에 따라 포함되는 구현이 달라지므로 함수 이름만으로 실행 동작을 판단할 수 없습니다.
 * CONFIG_IRQ_DOMAIN_HIERARCHY가 켜진 구현은 ops->alloc이 있으면 flags에 IRQ_DOMAIN_FLAG_HIERARCHY를 OR합니다. alloc이 없을 때 기존 비트를 지우는 else는 없습니다. 설정이 꺼진 쪽의 같은 이름 함수는 빈 본문입니다. 비계층 빌드의 irq_domain_alloc_irqs_locked는 인자와 무관하게 -EINVAL이고 irq_domain_free_one_irq는 빈 본문입니다. 런타임에 두 정의 중 하나를 선택하는 것이 아니라 전처리 조건에 맞는 구현을 컴파일합니다.
 * 초기 flags=0이고 alloc 유무가 다른 경우를 적으세요. flags에 계층 비트가 이미 켜졌는데 alloc이 없는 경우에도 이 함수가 비트를 지우지는 않음을 확인하세요.
 */
static void irq_domain_check_hierarchy(struct irq_domain *domain)
{
	/* Hierarchy irq_domains must implement callback alloc() */
	if (domain->ops->alloc)
		domain->flags |= IRQ_DOMAIN_FLAG_HIERARCHY;
}
#else	/* CONFIG_IRQ_DOMAIN_HIERARCHY */
/**
 * irq_domain_get_irq_data - Get irq_data associated with @virq and @domain
 * @domain:	domain to match
 * @virq:	IRQ number to get irq_data
 */
struct irq_data *irq_domain_get_irq_data(struct irq_domain *domain,
					 unsigned int virq)
{
	struct irq_data *irq_data = irq_get_irq_data(virq);

	return (irq_data && irq_data->domain == domain) ? irq_data : NULL;
}
EXPORT_SYMBOL_GPL(irq_domain_get_irq_data);

